    # 1) Navigate to the Orders grid using a relative URL.
    # 2) Locate the order with number "299" in the orders grid and open it.
    # 3) Click the Cancel control on the order view (try button then link).
    # 4) If a confirmation button appears, click a likely confirm button.
    # Notes: Use only accessibility-tree-centric selectors (page.get_by_role()).

    # Step 0: Knowledge base functions reasoning
    # There are no helper functions available in the knowledge base for this task, so none are used.

    # Step 1: Go to the Orders grid
    await page.goto("/index.php/admin/sales/order/index/")
    await page.wait_for_load_state("networkidle")

    # Step 2: Try to find the order link for 299.
    # First try a direct link whose accessible name contains "299".
    order_link = page.get_by_role("link", name="299")
    if await order_link.count() > 0:
        await order_link.first().click()
    else:
        # Fallback: find any row that contains a cell with name "299" and click the first link inside that row.
        row_with_order = page.get_by_role("row").filter(has=page.get_by_role("cell", name="299"))
        if await row_with_order.count() > 0:
            # try to click a link inside that row (order number is often a link)
            links_in_row = row_with_order.first().get_by_role("link")
            if await links_in_row.count() > 0:
                await links_in_row.first().click()
            else:
                # as a last resort click the cell directly
                await row_with_order.first().get_by_role("cell", name="299").first().click()
        else:
            # Another fallback: try common variants that might include a '#' prefix
            hash_link = page.get_by_role("link", name="#299")
            if await hash_link.count() > 0:
                await hash_link.first().click()
            else:
                raise Exception("Could not find order '299' on the Orders grid")

    # Wait for the order view to load
    await page.wait_for_load_state("networkidle")

    # Step 3: Click the Cancel control on the order view.
    cancelled = False
    # Preferred: button named "Cancel"
    try:
        cancel_button = page.get_by_role("button", name="Cancel")
        if await cancel_button.count() > 0:
            await cancel_button.first().click()
            cancelled = True
    except Exception:
        cancelled = False

    if not cancelled:
        # Some themes use a link instead of a button
        try:
            cancel_link = page.get_by_role("link", name="Cancel")
            if await cancel_link.count() > 0:
                await cancel_link.first().click()
                cancelled = True
        except Exception:
            cancelled = False

    if not cancelled:
        # Try any control that has text "Cancel" (less preferred but still accessibility-centred)
        try:
            any_cancel = page.get_by_role("button").filter(has=page.get_by_role("text", name="Cancel"))
            if await any_cancel.count() > 0:
                await any_cancel.first().click()
                cancelled = True
        except Exception:
            # ignore and continue to next fallback
            pass

    if not cancelled:
        # final fallback: try locating a button by several common confirmation-action labels (in case Cancel is nested)
        for label in ("Cancel Order", "Cancel This Order", "Void", "Cancel"):
            btn = page.get_by_role("button", name=label)
            if await btn.count() > 0:
                await btn.first().click()
                cancelled = True
                break

    if not cancelled:
        raise Exception("Could not find a Cancel control on the order view for order 299")

    # Step 4: If a confirmation appears, click a likely confirmation button.
    # Give a short pause for any modal to appear
    await page.wait_for_timeout(500)
    for confirm_name in ("OK", "Yes", "Confirm", "Continue", "Proceed"):
        try:
            confirm_btn = page.get_by_role("button", name=confirm_name)
            if await confirm_btn.count() > 0:
                await confirm_btn.first().click()
                break
        except Exception:
            pass

    # Wait for processing to complete
    await page.wait_for_load_state("networkidle")

    return

