            any_cancel = page.get_by_role("button").filter(has=page.get_by_role("text", name="Cancel"))
            if await any_cancel.count() > 0:
                await any_cancel.first().click()
                cancelled = True
        except Exception:
            # ignore and continue to next fallback
            pass

    if not cancelled:
        # final fallback: try locating a button by several common confirmation-action labels (in case Cancel is nested)
        for label in ("Cancel Order", "Cancel This Order", "Void", "Cancel"):
            btn = page.get_by_role("button", name=label)
            if await btn.count() > 0:
                await btn.first().click()
                cancelled = True
                break

    if not cancelled:
        raise Exception("Could not find a Cancel control on the order view for order 299")

    # Step 4: If a confirmation appears, click a likely confirmation button.
    # Give a short pause for any modal to appear
    await page.wait_for_timeout(500)
    for confirm_name in ("OK", "Yes", "Confirm", "Continue", "Proceed"):
        try:
            confirm_btn = page.get_by_role("button", name=confirm_name)
            if await confirm_btn.count() > 0:
                await confirm_btn.first().click()
                break
        except Exception:
            pass

    # Wait for processing to complete
    await page.wait_for_load_state("networkidle")

    return
